from tenacity import retry, stop_after_attempt, wait_exponential
import logging

@retry(
    stop=stop_after_attempt(3), # 最多尝试 3 次，包含首次调用，即最多额外重试 2 次。
    wait=wait_exponential(multiplier=1, min=2, max=10) # 指数退避等待
)
