def safe_parse_json(text: str) -> dict:
 """安全解析 LLM 输出的 JSON"""
 import json, re
 # 提取 JSON 部分(LLM 有时会加多余的说明文字)
    json_match = re.search(r'\{.*\}', text, re.DOTALL)
 if json_match:
 try:
 return json.loads(json_match.group())
 except json.JSONDecodeError:
 pass
 return {"error": "解析失败", "raw": text}
